import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design tokens
  const COLORS = {
    background: 0x0b0b10,
    surface: 0x14141a,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  const PLATE = {
    width: 1.9,
    height: 1.2,
    pitch: 1.5,
    count: 6,
    offsetX: 0.9,
  };

  const CAPTIONS = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE',
  ];

  // Load base texture
  const baseTexture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  baseTexture.colorSpace = THREE.SRGBColorSpace;

  const allMaterials = [];
  const plates = [];

  // Create headline text
  const headlineGeometry = ctx.fontAtlas.createTextGeometry({
    text: 'Inside the atelier',
    size: 0.62,
    family: 'Lora',
    weight: 600,
  });
  const headlineMaterial = new THREE.MeshBasicMaterial({ color: COLORS.paper });
  allMaterials.push(headlineMaterial);
  const headlineText = new THREE.Mesh(headlineGeometry, headlineMaterial);
  headlineText.position.set(-1.6, 1.9, 0);
  group.add(headlineText);

  // Create 6 plates
  for (let i = 0; i < PLATE.count; i++) {
    // Create plate geometry
    const plateGeometry = new THREE.PlaneGeometry(PLATE.width, PLATE.height);

    // Apply UV offset for visual variety across plates
    const uvAttribute = plateGeometry.getAttribute('uv');
    const uvArray = uvAttribute.array;
    const offset = (i * 0.167) % 1.0;
    for (let j = 0; j < uvArray.length; j += 2) {
      uvArray[j] = (uvArray[j] + offset) % 1.0;
    }
    uvAttribute.needsUpdate = true;

    // Plate material with PBR (machined metal aesthetic)
    const plateMaterial = new THREE.MeshPhysicalMaterial({
      map: baseTexture,
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
      clearcoatRoughness: 0.8,
    });
    allMaterials.push(plateMaterial);

    const plateMesh = new THREE.Mesh(plateGeometry, plateMaterial);
    plateMesh.position.x = PLATE.offsetX;
    plateMesh.position.y = i * PLATE.pitch - (PLATE.count - 1) * PLATE.pitch / 2;
    plateMesh.position.z = 0;
    plateMesh.userData.baseY = plateMesh.position.y;

    // Add bevel frame (machined edge)
    const bevelGeometry = new THREE.BoxGeometry(
      PLATE.width + 0.06,
      PLATE.height + 0.06,
      0.03
    );
    const bevelMaterial = new THREE.MeshStandardMaterial({
      color: COLORS.ink,
      roughness: 0.5,
      metalness: 0.5,
    });
    allMaterials.push(bevelMaterial);
    const bevelMesh = new THREE.Mesh(bevelGeometry, bevelMaterial);
    bevelMesh.position.z = -0.02;
    plateMesh.add(bevelMesh);

    // Add accent strip (left edge, visible when focused)
    const stripGeometry = new THREE.PlaneGeometry(0.03, PLATE.height + 0.06);
    const stripMaterial = new THREE.MeshBasicMaterial({
      color: COLORS.accent,
      emissive: COLORS.accent,
      emissiveIntensity: 1.4,
      toneMapped: false,
    });
    allMaterials.push(stripMaterial);
    const stripMesh = new THREE.Mesh(stripGeometry, stripMaterial);
    stripMesh.position.x = -(PLATE.width + 0.06) / 2 - 0.015;
    stripMesh.position.z = 0.02;
    stripMesh.visible = false;
    plateMesh.userData.accentStrip = stripMesh;
    plateMesh.add(stripMesh);

    // Add caption text
    const captionGeometry = ctx.fontAtlas.createTextGeometry({
      text: CAPTIONS[i],
      size: 0.18,
      family: 'JetBrains Mono',
      weight: 400,
    });
    const captionMaterial = new THREE.MeshBasicMaterial({
      color: COLORS.paper,
      transparent: true,
      opacity: 0,
    });
    allMaterials.push(captionMaterial);
    const captionText = new THREE.Mesh(captionGeometry, captionMaterial);
    captionText.position.set(-1.6, -PLATE.height / 2 - 0.15, 0);
    plateMesh.userData.captionMesh = captionText;
    plateMesh.add(captionText);

    group.add(plateMesh);
    plates.push(plateMesh);
  }

  // Animation state
  const scrollState = {
    y: 0,
    velocity: 0,
  };

  let settleTimeline = null;
  let settleTimeout = null;

  // Update plate positions with seamless looping
  const updatePlatePositions = () => {
    const loopHeight = PLATE.pitch * PLATE.count;

    plates.forEach((plate) => {
      const baseY = plate.userData.baseY;
      let currentY = baseY - scrollState.y;

      // Seamless wrap-around with modulo
      const offset = Math.floor((currentY + loopHeight / 2) / loopHeight);
      currentY -= offset * loopHeight;

      plate.position.y = currentY;
    });
  };

  // Update focus state for plate nearest to y=0
  const updateFocus = () => {
    let focusedPlate = null;
    let minDistance = Infinity;

    plates.forEach((plate) => {
      const dist = Math.abs(plate.position.y);
      if (dist < minDistance) {
        minDistance = dist;
        focusedPlate = plate;
      }
    });

    plates.forEach((plate) => {
      const isFocused = plate === focusedPlate;

      // Scale animation: 1.0 → 1.06
      gsap.to(plate.scale, {
        x: isFocused ? 1.06 : 1.0,
        y: isFocused ? 1.06 : 1.0,
        duration: 0.35,
        ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
        overwrite: 'auto',
      });

      // Accent strip visibility
      if (plate.userData.accentStrip) {
        plate.userData.accentStrip.visible = isFocused;
      }

      // Caption fade-in/out
      if (plate.userData.captionMesh) {
        const targetOpacity = isFocused ? 1 : 0;
        gsap.to(plate.userData.captionMesh.material, {
          opacity: targetOpacity,
          duration: 0.3,
          overwrite: 'auto',
        });
      }
    });
  };

  // Settle to nearest plate with weighted-settle motion
  const settleToNearest = () => {
    if (settleTimeline) {
      settleTimeline.kill();
      settleTimeline = null;
    }

    // Find nearest plate base position
    let targetY = scrollState.y;
    let minDistance = Infinity;

    plates.forEach((plate) => {
      const distance = Math.abs(plate.userData.baseY - scrollState.y);
      if (distance < minDistance) {
        minDistance = distance;
        targetY = plate.userData.baseY;
      }
    });

    settleTimeline = gsap.to(scrollState, {
      y: targetY,
      duration: 0.9,
      ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
      onUpdate: () => {
        updatePlatePositions();
        updateFocus();
      },
      onComplete: () => {
        settleTimeline = null;
      },
    });
  };

  // Scroll/wheel event handler
  const onScrollEvent = (event) => {
    const wheelDelta = event.deltaY || 0;
    scrollState.velocity = wheelDelta * 0.0015;
    scrollState.y += scrollState.velocity;

    // Cancel any in-progress settle animation
    if (settleTimeline) {
      settleTimeline.kill();
      settleTimeline = null;
    }

    clearTimeout(settleTimeout);

    // Update immediately
    updatePlatePositions();
    updateFocus();

    // Schedule settle after scroll stops (debounce with inertia damping)
    settleTimeout = setTimeout(settleToNearest, 150);
  };

  // Attach event handlers
  group.userData.handlers = {
    scroll: onScrollEvent,
  };

  // Apply cinematic primitives from config
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives && ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    });
  }

  // Initialize focus state
  updateFocus();

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill all GSAP animations
    gsap.killTweensOf(scrollState);
    plates.forEach(plate => {
      gsap.killTweensOf(plate.scale);
      if (plate.userData.captionMesh) {
        gsap.killTweensOf(plate.userData.captionMesh.material);
      }
    });

    if (settleTimeline) {
      settleTimeline.kill();
      settleTimeline = null;
    }
    clearTimeout(settleTimeout);

    // Dispose materials
    allMaterials.forEach(mat => {
      if (mat && mat.dispose) mat.dispose();
    });

    // Dispose geometries
    headlineGeometry.dispose();
    plates.forEach(plate => {
      plate.geometry.dispose();
      plate.children.forEach(child => {
        if (child.geometry) child.geometry.dispose();
      });
    });

    // Dispose texture
    if (baseTexture.dispose) baseTexture.dispose();
  };

  return group;
}
